// Export vendors to Excel using dynamic import of xlsx, with CSV fallback if xlsx is unavailable
export async function exportVendorsToExcel(data, filename = 'vendors-report') {
  if (!Array.isArray(data) || data.length === 0) return;
  try {
    const XLSX = await import(/* webpackChunkName: "xlsx" */ 'xlsx');
    const workbook = XLSX.utils.book_new();
    const worksheet = XLSX.utils.json_to_sheet(data);

    // Set helpful column widths
    worksheet['!cols'] = [
      { wch: 20 }, // Vendor Name
      { wch: 25 }, // Email
      { wch: 20 }, // Contact Person
      { wch: 15 }, // Phone
      { wch: 10 }, // Status
      { wch: 15 }, // Category
      { wch: 10 }, // Rating
      { wch: 15 }, // Total Spend
      { wch: 10 }, // Total POs
      { wch: 12 }, // Pending POs
      { wch: 10 }, // Total Jobs
      { wch: 15 }, // City
      { wch: 15 }, // State
      { wch: 30 }, // Services
      { wch: 15 }, // Last Activity
      { wch: 15 }, // Date Created
    ];

    XLSX.utils.book_append_sheet(workbook, worksheet, 'Vendors');

    // Write to blob and download to avoid FileSystem restrictions
    const wbout = XLSX.write(workbook, { bookType: 'xlsx', type: 'array' });
    const blob = new Blob([wbout], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${filename}.xlsx`;
    a.click();
    window.URL.revokeObjectURL(url);
  } catch (err) {
    console.warn('xlsx not found, falling back to CSV export', err);
    exportVendorsToCSV(data, filename);
  }
}

export function exportVendorsToCSV(data, filename = 'vendors-report') {
  if (!Array.isArray(data) || data.length === 0) return;
  const headers = Object.keys(data[0] || {});
  const rows = [headers.join(',')];
  for (const row of data) {
    rows.push(headers.map((h) => csvSanitize(row[h])).join(','));
  }
  const csv = rows.join('\n');
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const link = document.createElement('a');
  const url = URL.createObjectURL(blob);
  link.setAttribute('href', url);
  link.setAttribute('download', `${filename}.csv`);
  link.style.visibility = 'hidden';
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
}

function csvSanitize(value) {
  if (value === null || value === undefined) return '';
  const str = String(value);
  if (str.includes(',') || str.includes('\n') || str.includes('"')) {
    return '"' + str.replace(/"/g, '""') + '"';
    }
  return str;
}